311	/// Load split-file definitions and return a synthetic YAML value.
312	///
313	/// Reads each file in `paths`, wraps its content under `top_key.<stem>`,
314	/// and merges them all into one value. For example, `.bivvy/steps/database.yml`
315	/// becomes `{ steps: { database: <file content> } }`.
316	///
317	/// # Errors
318	///
319	/// Returns `ConfigParseError` if any file cannot be read or parsed.
320	fn load_split_files(paths: &[PathBuf], top_key: &str) -> Result<Option<serde_yaml::Value>> {
321	    if paths.is_empty() {
322	        return Ok(None);
323	    }
324	
325	    let mut entries = serde_yaml::Mapping::new();
326	
327	    for path in paths {
328	        let stem = path.file_stem().and_then(|s| s.to_str()).ok_or_else(|| {
329	            BivvyError::ConfigParseError {
330	                path: path.clone(),
331	                message: "Could not determine name from filename".to_string(),
332	            }
333	        })?;
334	
335	        let value = load_config_value(path)?;
336	
337	        entries.insert(serde_yaml::Value::String(stem.to_string()), value);
338	    }
339	
340	    let mut wrapper = serde_yaml::Mapping::new();
341	    wrapper.insert(
342	        serde_yaml::Value::String(top_key.to_string()),
343	        serde_yaml::Value::Mapping(entries),
344	    );
345	
346	    Ok(Some(serde_yaml::Value::Mapping(wrapper)))
347	}
