490	/// Collect config values in merge order, including split files.
491	///
492	/// Merge order:
493	/// 1. Remote base configs (from `extends:`)
494	/// 2. User global config (`~/.bivvy/config.yml`)
495	/// 3. Project config (`.bivvy/config.yml`)
496	/// 4. Split-file steps (`.bivvy/steps/*.yml`)
497	/// 5. Split-file workflows (`.bivvy/workflows/*.yml`) — selection
498	///    determines which files participate.
499	/// 6. Local overrides (`.bivvy/config.local.yml`)
500	fn collect_config_values(
501	    paths: &ConfigPaths,
502	    workflows: WorkflowSelection<'_>,
503	) -> Result<Vec<serde_yaml::Value>> {
504	    let mut configs = Vec::new();
505	
506	    // 1. Remote extends (populated later by resolver)
507	    for p in &paths.extends {
508	        configs.push(load_config_value(p)?);
509	    }
510	
511	    // 2. User global
512	    if let Some(p) = &paths.user_global {
513	        configs.push(load_config_value(p)?);
514	    }
515	
516	    // 3. Project config
517	    if let Some(p) = &paths.project {
518	        configs.push(load_config_value(p)?);
519	    }
520	
521	    // 4. Split-file steps
522	    if let Some(v) = load_split_files(&paths.split_steps, "steps")? {
523	        configs.push(v);
524	    }
525	
526	    // 5. Split-file workflows (selected per request)
527	    match workflows {
528	        WorkflowSelection::All => {
529	            if let Some(v) = load_split_workflow_files_all(&paths.split_workflows)? {
530	                configs.push(v);
531	            }
532	        }
533	        WorkflowSelection::One(name) => {
534	            if let Some(path) = paths.split_workflows.iter().find(|p| {
535	                p.file_stem()
536	                    .and_then(|s| s.to_str())
537	                    .is_some_and(|stem| stem == name)
538	            }) {
539	                let file = load_single_workflow_file(path)?;
540	                configs.push(workflow_file_to_partial(&file, name)?);
541	            }
542	        }
543	        WorkflowSelection::None => {}
544	    }
545	
546	    // 6. Local overrides
547	    if let Some(p) = &paths.project_local {
548	        configs.push(load_config_value(p)?);
549	    }
550	
551	    Ok(configs)
552	}
