    use crate::session::{SessionId, SessionMetadata, StepResultSummary};

    fn test_entry(message: &str) -> FeedbackEntry {
        FeedbackEntry {
            id: "fb_test123456".to_string(),
            timestamp: None,
            message: message.to_string(),
            tags: vec![],
            session_id: None,
