            staged_at: Utc::now(),
        };

        let json = serde_json::to_string(&staged).unwrap();
        let parsed: StagedUpdate = serde_json::from_str(&json).unwrap();

        assert_eq!(parsed.version, "2.0.0");
    }

    #[test]
    fn staging_dir_returns_path() {
        // On most systems crate::sys::data_dir() is Some
