        let content = fs::read_to_string(logger.log_path()).unwrap();
        let lines: Vec<&str> = content.lines().collect();
        assert_eq!(lines.len(), 10);

        // Each line should be independently parseable JSON
        for (i, line) in lines.iter().enumerate() {
